// Планы тренировок. Единственный источник правды по дням программы.
//
// До 1.1.0 план был один и жил в workoutTabHelpers.jsx константой PROGRAM_DAYS.
// С 1.1.0 планов несколько: у профиля есть plan_id (какой план сейчас ведётся),
// у каждой тренировки — plan_id (к какому плану относится её program_day).
// Это обязательно: номер дня — ссылка на шаблон внутри плана, и «день 7» в
// старом плане и в новом — разные тренировки. Без plan_id экспорт недели и
// «пропущено» сверяли бы запись не с тем шаблоном.
//
// Старый план (plan1) остаётся в базе как есть: все тренировки до 1.1.0
// получили plan_id = 'plan1' значением по умолчанию колонки.
//
// Формат дня:
//   day       — номер в цикле, 1..days.length;
//   type      — 'strength' | 'cardio' | 'pool';
//   title     — название дня (оно же в шапке тренировки и в экспорте);
//   warmup    — ключ подсказки разминки (WARMUP_TIPS), если не совпадает с title;
//   cooldown  — ключ набора заминки (COOLDOWN_SETS), если не угадывается по title;
//   exercises — [{ name, sets, reps, where?, tip? }] для силового дня;
//   cardio    — { name, distance?, incline?, duration? } для кардио и бассейна.
//
// Названия упражнений — ровно те, что уже есть в истории: рекорды, прогресс и
// «прошлая неделя» в экспорте сопоставляются по имени.

