// «4×8-10» → { sets: 4, reps: '8-10' }.
function parseSetsReps(s) {
  const m = String(s).match(/^(\d+)\s*×\s*(.+)$/);
  return m ? { sets: parseInt(m[1], 10), reps: m[2].trim() } : { sets: 1, reps: String(s) };
}

function buildPlan2Days() {
  const days = [];
  for (let week = 1; week <= 4; week += 1) {
    PLAN2_TEMPLATES.forEach((tpl, wd) => {
      days.push({
        day: (week - 1) * PLAN2_TEMPLATES.length + wd + 1,
        type: 'strength',
        title: tpl.title,
        warmup: tpl.warmup,
        cooldown: tpl.cooldown,
        exercises: tpl.exercises.map(([name, where, weeks, tips]) => {
          const { sets, reps } = parseSetsReps(weeks[week - 1]);
          const tip = tips ? (tips[week] || tips.all) : null;
          return {
            name, sets, reps,
            ...(where ? { where } : {}),
            ...(tip ? { tip } : {}),
          };
        }),
      });
    });
  }
  return days;
}

const PLAN2_DAYS = buildPlan2Days();

